// 1. TYPES (Single Source of Truth)
// ==============================

import {
  ExtendedMainModule,
  SimulationProperties,
  repositionWithAutopilot,
  notifyUser,
} from './core'

import { LayoutTypes } from '../src/wasm/siminterface.ts'

export interface WaitForUserOptions {
  title: string
  message?: string
  buttonLabel?: string
  replace?: boolean
}

export interface QuestionChoice {
  id: string
  label: string
}

interface BaseQuestionOptions {
  id?: string
  title: string
  question: string
  replace?: boolean
}

export interface MultipleChoiceQuestionOptions extends BaseQuestionOptions {
  type: 'multiple-choice'
  choices: QuestionChoice[]
  correctAnswer?: string
  correctFeedback?: string
  incorrectFeedback?: string
}

export interface EssayQuestionOptions extends BaseQuestionOptions {
  type: 'essay'
  placeholder?: string
  minLength?: number
  submitLabel?: string
}

export type AskQuestionOptions = MultipleChoiceQuestionOptions | EssayQuestionOptions

export interface QuestionResult {
  questionId?: string
  type: AskQuestionOptions['type']
  answer: string
  correct?: boolean
  attempts: number
  elapsedMs: number
  cancelled?: boolean
}

export interface ScriptContext {
  controls: ExtendedMainModule
  props: any
  repositionWithAutopilot: typeof repositionWithAutopilot
  waitFor: (ms: number) => Promise<void>
  waitForCondition: (
    condition: () => boolean,
    confirmationMs?: number,
    pollIntervalMs?: number,
    hardTimeoutMs?: number | null,
    throwOnTimeout?: boolean,
  ) => Promise<boolean>

  notifyUser: typeof notifyUser
  /** Pause lesson progression until the user acknowledges the prompt. */
  waitForUser: (options: WaitForUserOptions) => Promise<void>
  /** Ask a multiple-choice or essay question and return the submitted result. */
  askQuestion: (options: AskQuestionOptions) => Promise<QuestionResult>
  dataView: (prop: SimulationProperties, state: boolean) => void
  plotView: (prop: SimulationProperties | SimulationProperties[], state: boolean) => void
  dataDisplayReset: () => void
  setLayout: (mode: LayoutTypes) => void
  layoutTypes: typeof LayoutTypes
  setVisuals: (state: boolean) => void
  setMap: (state: boolean) => void
  setTheme: (dark: boolean) => void
  setTab: {
    (panelId: 'cockpit', tabName: 'Cockpit'): void
    (panelId: 'realtime', tabName: 'Real-Time-Data' | 'Airflow'): void
    (panelId: 'simulation', tabName: 'Simulation'): void
    (panelId: 'learning-modules', tabName: 'Learning-Modules'): void
    (panelId: 'autopilot', tabName: 'Autopilot'): void
    (panelId: 'flight-model', tabName: 'Flight-Model' | 'Joystick'): void
    (panelId: 'classroom', tabName: 'Classroom'): void
    (panelId: 'prompt', tabName: 'Prompt' | 'whiteboard'): void
  }
  resetPanels: () => void
  checkPoint: (content: string) => void
  metrics: any[]
}

// ==============================
// 2. CONTEXT FACTORY (ONLY PLACE YOU UPDATE)
// ==============================

export function createScriptContext(deps: ScriptContext): ScriptContext {
  return {
    controls: deps.controls,
    props: deps.props,
    repositionWithAutopilot: deps.repositionWithAutopilot,
    waitFor: deps.waitFor,
    waitForCondition: deps.waitForCondition,
    notifyUser: deps.notifyUser,
    waitForUser: deps.waitForUser,
    askQuestion: deps.askQuestion,
    dataView: deps.dataView,
    plotView: deps.plotView,
    dataDisplayReset: deps.dataDisplayReset,
    checkPoint: deps.checkPoint,
    setLayout: deps.setLayout,
    layoutTypes: LayoutTypes,
    setVisuals: deps.setVisuals,
    setMap: deps.setMap,
    setTheme: deps.setTheme,
    setTab: deps.setTab,
    resetPanels: deps.resetPanels,
    metrics: deps.metrics,
  }
}

// ==============================
// 3. SCRIPT RUNNER
// ==============================

export type UserScript = (ctx: ScriptContext) => Promise<void>

export async function runUserScript(script: UserScript, ctx: ScriptContext) {
  try {
    await script(ctx)
  } catch (err) {
    console.error('Script execution failed:', err)
    ctx.notifyUser('Script Error', String(err))
    throw err
  }
}

